package io.github.jesterportfolio.hearth.combat;

import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.combat.CombatRetryVote.*;

final class CombatRetryVoteTest {
    static final class Fixture {
        final CombatAttemptTest.Fixture combat;final AtomicLong clock=new AtomicLong(100);final List<String> notices=new ArrayList<>();boolean current=true;
        final CombatRetryVote vote;
        Fixture(){this(2);}Fixture(int count){combat=new CombatAttemptTest.Fixture(CombatAttemptTest.content(CombatContent.Pool.SHARED,2,CombatContent.LocationMode.START),count);vote=new CombatRetryVote(combat.fight,combat.work::add,()->{},clock::get,Duration.ofSeconds(30),()->current,notices::add);}
        View start(){return vote.request(combat.p,combat.one);}
        CompletionStage<View> cast(View view,Choice choice){return vote.cast(combat.p,combat.one,view.id(),choice);}
        void yesBoth(View view){cast(view,Choice.YES);vote.cast(combat.q,combat.two,view.id(),Choice.YES);combat.pump();}
    }
    @Test void majorityClosesInputBeforeOneExistingAttemptIsEnded(){var f=new Fixture();var v=f.start();assertEquals(30,v.remainingSeconds());assertEquals(2,v.targets());f.cast(v,Choice.YES);assertEquals(Phase.OPEN,f.vote.view().phase());assertEquals(CombatAttempt.Phase.ACTIVE,f.combat.fight.snapshot().phase());var done=f.vote.cast(f.combat.q,f.combat.two,v.id(),Choice.YES);assertEquals(Phase.INPUT_CLOSED,f.vote.view().phase());assertFalse(done.toCompletableFuture().isDone());assertFalse(f.vote.barrier().toCompletableFuture().isDone());f.combat.pump();assertEquals(Phase.RETRY_REQUESTED,done.toCompletableFuture().join().phase());assertEquals(CombatAttempt.Outcome.RETRY,f.combat.fight.snapshot().outcome());var receipt=f.vote.view().receipt();long revision=f.combat.fight.snapshot().revision();assertEquals(receipt,f.start().receipt());assertTrue(f.cast(v,Choice.YES).toCompletableFuture().isCompletedExceptionally());assertEquals(revision,f.combat.fight.snapshot().revision());assertEquals(receipt,f.vote.view().receipt());}
    @Test void spectatorCanRequestAndVoteBeforeOrDuringWipe(){var f=new Fixture();f.combat.deadP();f.combat.fight.died(f.combat.q,f.combat.two,f.combat.pose);assertEquals(CombatAttempt.Phase.WIPE_WAIT,f.combat.fight.snapshot().phase());f.yesBoth(f.start());assertEquals(Phase.RETRY_REQUESTED,f.vote.view().phase());assertTrue(f.combat.member(f.combat.p.playerId()).dead());assertTrue(f.combat.member(f.combat.q.playerId()).dead());}
    @Test void soloRequiresExplicitYesAndDoesNotAutomaticallyRestart(){var f=new Fixture(1);var v=f.start();assertEquals(Phase.OPEN,v.phase());var result=f.cast(v,Choice.YES);assertFalse(result.toCompletableFuture().isDone());f.combat.pump();assertEquals(Phase.RETRY_REQUESTED,result.toCompletableFuture().join().phase());assertTrue(f.notices.stream().anyMatch(s->s.contains("아직 연결되지 않아 대기")));}
    @Test void duplicateInputRejectedWhileOpenAndAbstainNoVoteNeverCountAsYes(){for(var choice:List.of(Choice.NO,Choice.ABSTAIN)){var f=new Fixture();var v=f.start();f.cast(v,Choice.YES);assertTrue(f.cast(v,choice).toCompletableFuture().isCompletedExceptionally());f.vote.cast(f.combat.q,f.combat.two,v.id(),choice);assertEquals(Phase.OPEN,f.vote.view().phase());f.clock.addAndGet(Duration.ofSeconds(30).toNanos());f.vote.poll();assertEquals(Phase.UNDECIDED,f.vote.view().phase());assertEquals(CombatAttempt.Outcome.NONE,f.combat.fight.snapshot().outcome());assertNotEquals(v.id(),f.start().id());}}
    @Test void noVoteAndDeadlineRejectLateYes(){var f=new Fixture(1);var v=f.start();f.clock.addAndGet(Duration.ofSeconds(30).toNanos());assertTrue(f.cast(v,Choice.YES).toCompletableFuture().isCompletedExceptionally());assertEquals(Phase.UNDECIDED,f.vote.view().phase());assertEquals(CombatAttempt.Outcome.NONE,f.combat.fight.snapshot().outcome());}
    @Test void openRosterChangeCancelsOldInputAndStartsNewRosterWithoutChangingDifficulty(){var f=new Fixture();var v=f.start();f.vote.cast(f.combat.q,f.combat.two,v.id(),Choice.YES);f.combat.fight.disconnect(f.combat.q,f.combat.two,f.combat.pose);f.vote.poll();var replacement=f.vote.view();assertNotEquals(v.id(),replacement.id());assertEquals(1,replacement.targets());assertEquals(0,replacement.yes());assertEquals(2,f.combat.fight.snapshot().difficultyPlayers());assertTrue(f.cast(v,Choice.YES).toCompletableFuture().isCompletedExceptionally());f.cast(replacement,Choice.YES);f.combat.pump();assertEquals(Phase.RETRY_REQUESTED,f.vote.view().phase());}
    @Test void reconnectWithSameUuidButNewSessionAlsoReplacesOpenVote(){var f=new Fixture();var v=f.start();f.combat.fight.disconnect(f.combat.q,f.combat.two,f.combat.pose);var next=new Object();f.combat.fight.reconnect(f.combat.q,next);f.combat.fight.returned(f.combat.q,next);f.vote.poll();var fresh=f.vote.view();assertNotEquals(v.id(),fresh.id());assertEquals(2,fresh.targets());assertTrue(f.vote.cast(f.combat.q,f.combat.two,fresh.id(),Choice.YES).toCompletableFuture().isCompletedExceptionally());assertFalse(f.vote.cast(f.combat.q,next,fresh.id(),Choice.YES).toCompletableFuture().isCompletedExceptionally());}
    @Test void inputClosedRosterChangeDoesNotRecalculateAcceptedMajority(){var f=new Fixture();var v=f.start();f.cast(v,Choice.YES);f.vote.cast(f.combat.q,f.combat.two,v.id(),Choice.YES);f.combat.fight.disconnect(f.combat.q,f.combat.two,f.combat.pose);f.vote.poll();assertEquals(2,f.vote.view().targets());assertEquals(2,f.vote.view().yes());f.combat.pump();assertEquals(Phase.RETRY_REQUESTED,f.vote.view().phase());}
    @Test void anotherRunSessionOrVoteCannotChangeThisVote(){var f=new Fixture();var other=new Fixture();var v=f.start();var ov=other.start();assertTrue(f.vote.cast(other.combat.p,other.combat.one,v.id(),Choice.YES).toCompletableFuture().isCompletedExceptionally());assertTrue(f.vote.cast(f.combat.p,new Object(),v.id(),Choice.YES).toCompletableFuture().isCompletedExceptionally());assertTrue(f.cast(ov,Choice.YES).toCompletableFuture().isCompletedExceptionally());assertEquals(0,f.vote.view().yes());assertEquals(Phase.OPEN,other.vote.view().phase());}
    @Test void pendingRevivalDrainsBeforeRetryAndUsesOneBarrier(){var f=new Fixture();f.combat.deadP();f.combat.fight.revive(f.combat.p,f.combat.one,UUID.randomUUID(),"rescue");var v=f.start();f.yesBoth(v);assertEquals(Phase.INPUT_CLOSED,f.vote.view().phase());assertEquals(CombatAttempt.Outcome.NONE,f.combat.fight.snapshot().outcome());assertFalse(f.vote.barrier().toCompletableFuture().isDone());f.combat.port.applies.getFirst().result().complete(true);f.combat.pump();assertEquals(Phase.RETRY_REQUESTED,f.vote.view().phase());assertEquals(1,f.combat.fight.snapshot().sharedUsed());}
    @Test void failedRevivalHoldsWithoutReportingRetrySuccess(){var f=new Fixture();f.combat.deadP();f.combat.fight.revive(f.combat.p,f.combat.one,UUID.randomUUID(),"rescue");var v=f.start();f.yesBoth(v);f.combat.port.applies.getFirst().result().complete(false);f.combat.pump();assertEquals(Phase.HOLD,f.vote.view().phase());assertNull(f.vote.view().receipt());assertTrue(f.vote.barrier().toCompletableFuture().isCompletedExceptionally());assertEquals(CombatAttempt.Outcome.NONE,f.combat.fight.snapshot().outcome());}
    @Test void earlierVictoryOrAllOfflineResultCannotBeOverwritten(){for(boolean victory:List.of(true,false)){var f=new Fixture();var v=f.start();f.cast(v,Choice.YES);f.vote.cast(f.combat.q,f.combat.two,v.id(),Choice.YES);if(victory)f.combat.fight.victory();else{f.combat.fight.disconnect(f.combat.p,f.combat.one,f.combat.pose);f.combat.fight.disconnect(f.combat.q,f.combat.two,f.combat.pose);}f.combat.pump();assertEquals(Phase.CANCELLED,f.vote.view().phase());assertNull(f.vote.view().receipt());assertFalse(f.vote.barrier().toCompletableFuture().isCompletedExceptionally());assertEquals(victory?CombatAttempt.Outcome.VICTORY:CombatAttempt.Outcome.ALL_OFFLINE,f.combat.fight.snapshot().outcome());}}
    @Test void invalidScopeOrShutdownCannotApplyLateDecision(){for(boolean shutdown:List.of(true,false)){var f=new Fixture();var v=f.start();f.cast(v,Choice.YES);f.vote.cast(f.combat.q,f.combat.two,v.id(),Choice.YES);if(shutdown)f.vote.close();else{f.current=false;f.vote.poll();}f.combat.pump();assertEquals(Phase.HOLD,f.vote.view().phase());assertNull(f.vote.view().receipt());assertEquals(CombatAttempt.Outcome.NONE,f.combat.fight.snapshot().outcome());assertTrue(f.vote.barrier().toCompletableFuture().isCompletedExceptionally());}}
    @Test void rejectedOwnerDeliveryHoldsWithoutEndingAttempt(){var f=new Fixture(1);var vote=new CombatRetryVote(f.combat.fight,r->{throw new RejectedExecutionException();},()->{},f.clock::get,Duration.ofSeconds(30),()->true,s->{});var v=vote.request(f.combat.p,f.combat.one);assertTrue(vote.cast(f.combat.p,f.combat.one,v.id(),Choice.YES).toCompletableFuture().isCompletedExceptionally());vote.poll();assertEquals(Phase.HOLD,vote.view().phase());assertEquals(CombatAttempt.Outcome.NONE,f.combat.fight.snapshot().outcome());}
    @Test void strictChatParserRejectsCrossCommandOrExtraArguments(){UUID id=UUID.randomUUID();assertEquals(new Input(id,Choice.YES),CombatRetryVote.input("/hearthcombat vote "+id+" yes").orElseThrow());for(String line:List.of("/hearthstory vote "+id+" yes","/hearthcombat vote "+id+" yes other","/hearthcombat vote wrong yes","/hearthcombat vote "+id+" YES","/hearthcombat vote 1-1-1-1-1 yes"))assertTrue(CombatRetryVote.input(line).isEmpty());}
}
